61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Dedicated audit logger for owner lifecycle side-effects. */
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    /**
70	     * Pragmatic check for a syntactically valid email address: a non-empty local
71	     * part, a single '@', and a domain with at least one dot-separated label.
72	     */
73	    private static final Pattern EMAIL_PATTERN =
74	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
75	
76	    /**
77	     * Disposable email domains that are rejected: an owner email whose domain is one of
78	     * these is treated as invalid so the create/update is rejected with 400. Compared
79	     * case-insensitively against the normalized (lower-cased) email domain.
80	     */
81	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
82	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
83	
84	    /**
85	     * Common street-type abbreviations expanded during address normalization,
86	     * keyed by their upper-cased form.
87	     */
88	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
89	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
90	
91	    /**
92	     * Required national-number length keyed by E.164 country calling code: a
93	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'}
94	     * (NANP) number carries 10. A number whose country code is listed here must have
95	     * exactly the mandated number of national digits.
96	     */
97	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
98	        Map.of("61", 9, "1", 10);
99	
100	    /**
101	     * Inclusive 4-digit postcode range {@code {low, high}} keyed by the region derived
102	     * from the owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose
103	     * region is not listed here (see {@link OwnerMapper#CITY_REGION}) accepts any 4-digit
104	     * postcode.
105	     */
106	    private static final Map<String, int[]> REGION_POSTCODE_RANGES =
107	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
108	            "QLD", new int[] {4000, 4099});
109	
110	    private final ClinicService clinicService;
111	
112	    private final OwnerMapper ownerMapper;
113	
114	    private final PetMapper petMapper;
115	
116	    private final VisitMapper visitMapper;
