128	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
129	    @Override
130	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
131	        Collection<Owner> owners;
132	        if (lastName != null) {
133	            owners = this.clinicService.findOwnerByLastName(lastName);
134	        } else {
135	            owners = this.clinicService.findAllOwners();
136	        }
137	        if (owners.isEmpty()) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
141	    }
