143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
146	        Owner owner = this.clinicService.findOwnerById(ownerId);
147	        if (owner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
151	    }
152	
153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Override
155	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
156	        // Validate & normalize the optional email; reject the create when it is present but invalid.
157	        if (!normalizeEmail(ownerFieldsDto)) {
158	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
159	        }
160	        // Validate & normalize the optional postcode; reject the create when it is present but
161	        // not valid for the owner's city (see normalizePostcode).
162	        if (!normalizePostcode(ownerFieldsDto)) {
163	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
164	        }
165	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
166	        // abbreviations) and store the normalized form back on the DTO so it is what gets
167	        // persisted and compared. Reject the create when the address is blank once normalized.
168	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
169	        if (canonicalAddress.isBlank()) {
170	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
171	        }
172	        ownerFieldsDto.setAddress(canonicalAddress);
173	        // Reject the create when the owner's city is already at capacity, i.e. it already
174	        // contains 50 or more owners (compared case-insensitively).
175	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
176	            return new ResponseEntity<>(HttpStatus.CONFLICT);
177	        }
178	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
179	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
180	        if (normalizedTelephone == null) {
181	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
182	        }
183	        ownerFieldsDto.setTelephone(normalizedTelephone);
184	        // Consolidated duplicate detection. All former separate telephone, email and household
185	        // duplicate checks are now expressed through the single derived identity key
186	        // '<normalizedTelephone>|<email or empty>|<householdId>' (see OwnerMapper#identityKey).
187	        // A create is rejected only when the new owner's identity collides with an existing owner's.
188	        // Because the telephone is part of the identity, two members of the same household with
189	        // different telephones no longer collide and are both allowed; only owners that share the
190	        // same normalized telephone and email are treated as the same identity.
191	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
192	        String contactIdentity = identityContact(candidate);
193	        boolean identityInUse = this.clinicService.findAllOwners().stream()
194	            .anyMatch(existing -> contactIdentity.equals(identityContact(existing)));
195	        if (identityInUse) {
196	            return new ResponseEntity<>(HttpStatus.CONFLICT);
197	        }
198	        // Household duplicate detection keyed on the deterministic householdId, derived from the
199	        // normalized last name and postcode (see OwnerMapper#householdId). Owners sharing a last
200	        // name and postcode share the same household. A second owner in an existing household is
201	        // rejected as a household duplicate (409) unless the request declares 'sharesHousehold',
202	        // in which case it is created as a declared household member — 'sharesHousehold' only
203	        // bypasses this block; the household link itself now follows from the computed householdId.
204	        String householdId = ownerMapper.householdId(candidate);
205	        boolean householdExists = this.clinicService.findAllOwners().stream()
206	            .anyMatch(existing -> householdId.equals(ownerMapper.householdId(existing)));
207	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
208	        if (householdExists && !sharesHousehold) {
209	            return new ResponseEntity<>(HttpStatus.CONFLICT);
210	        }
211	        boolean declaredMember = householdExists && sharesHousehold;
212	        // Determine the effective registration date — the value supplied on the request, or the
213	        // server's current date when none was supplied — and roll it forward to the next business
214	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
215	        // registration date (membership-number year segment, per-day create-limit) uses this
216	        // adjusted date.
217	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
218	        if (registrationDate == null) {
219	            registrationDate = LocalDate.now();
220	        }
221	        // Reject a supplied registration date that lies in the future (later than the
222	        // server's current date): an owner cannot be registered ahead of time.
223	        else if (registrationDate.isAfter(LocalDate.now())) {
224	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
225	        }
226	        registrationDate = toBusinessDay(registrationDate);
227	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
228	        // owners have already been registered on this (adjusted) business day.
229	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
230	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
231	        }
232	        HttpHeaders headers = new HttpHeaders();
233	        Owner owner = candidate;
234	        owner.setRegistrationDate(registrationDate);
235	        // Assign the customer code as '<REGION>-<HASH8>': the region derived from the owner's
236	        // postcode (falling back to the city, then 'UNKNOWN') and the first 8 upper-case hex
237	        // characters of the SHA-256 of the normalized telephone concatenated with the last name.
238	        owner.setCustomerCode(customerCode(owner));
239	        // Record how many existing owners already share this owner's first and last name
240	        // (compared case-insensitively) at the moment before this owner is created.
241	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
242	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
243	        // registered on this (adjusted) business day before this owner is created.
244	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
245	        // Record the size of this owner's household after this create: the number of existing
246	        // owners sharing the same household (i.e. the same computed householdId) plus this owner.
247	        owner.setHouseholdSize(countHouseholdMembers(owner) + 1);
248	        // Flag a possible (soft) duplicate: this owner is not a hard identity duplicate, but it
249	        // shares an existing owner's last name (case-insensitively) and postcode while carrying a
250	        // different telephone. When such a match exists, record it as 'possibleDuplicate' with
251	        // 'possibleDuplicateOf' set to the matching owner's id; otherwise it is not a possible
252	        // duplicate. A declared household member is an acknowledged member, not a suspected
253	        // duplicate, so it is never flagged.
254	        if (declaredMember) {
255	            owner.setPossibleDuplicate(false);
256	            owner.setPossibleDuplicateOf(null);
257	        }
258	        else {
259	            Owner softMatch = findPossibleDuplicate(owner);
260	            owner.setPossibleDuplicate(softMatch != null);
261	            owner.setPossibleDuplicateOf(softMatch == null ? null : softMatch.getId());
262	        }
263	        this.clinicService.saveOwner(owner);
264	        // Emit an audit line recording the new owner's id, customer code, registration date
265	        // and membership level.
266	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
267	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
268	            ownerMapper.membershipLevel(owner));
269	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
270	        headers.setLocation(UriComponentsBuilder.newInstance()
271	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
272	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
273	    }
274	
275	    /**
276	     * Validate and normalize the optional owner email in place.
277	     *
278	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
279	     * When present it must be a syntactically valid address; a valid address is
280	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
281	     * present but syntactically invalid, so the caller can reject with 400.
282	     */
283	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
284	        String email = ownerFieldsDto.getEmail();
285	        if (email == null || email.isBlank()) {
286	            ownerFieldsDto.setEmail(null);
287	            return true;
288	        }
289	        String normalized = email.trim().toLowerCase(Locale.ROOT);
290	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
291	            return false;
292	        }
293	        // Reject addresses whose domain is on the disposable-domain blocklist.
294	        String domain = normalized.substring(normalized.indexOf('@') + 1);
295	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
296	            return false;
297	        }
298	        ownerFieldsDto.setEmail(normalized);
299	        return true;
300	    }
301	
302	    /**
303	     * Validate the optional owner postcode in place.
304	     *
305	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
306	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
307	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
308	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
309	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
310	     * when a postcode is present but malformed or out of range, so the caller can
311	     * reject with 400.
312	     */
313	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
314	        String postcode = ownerFieldsDto.getPostcode();
315	        if (postcode == null || postcode.isBlank()) {
316	            ownerFieldsDto.setPostcode(null);
317	            return true;
318	        }
319	        if (!postcode.matches("\\d{4}")) {
320	            return false;
321	        }
322	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
323	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
324	        if (range != null) {
325	            int value = Integer.parseInt(postcode);
326	            if (value < range[0] || value > range[1]) {
327	                return false;
328	            }
329	        }
330	        return true;
331	    }
332	
333	    /**
334	     * Normalize an owner address: trim, collapse each run of whitespace to a single
335	     * space, upper-case, and expand common street-type abbreviations
336	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
337	     * A {@code null} value normalizes to the empty string.
338	     */
339	    private static String normalizeAddress(String value) {
340	        if (value == null) {
341	            return "";
342	        }
343	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
344	        if (collapsed.isEmpty()) {
345	            return "";
346	        }
347	        String[] tokens = collapsed.split(" ");
348	        StringBuilder sb = new StringBuilder(collapsed.length());
349	        for (int i = 0; i < tokens.length; i++) {
350	            if (i > 0) {
351	                sb.append(' ');
352	            }
353	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
354	        }
355	        return sb.toString();
356	    }
357	
358	    /**
359	     * The contact portion of an owner's derived identity key: its normalized telephone and
360	     * email ('&lt;normalizedTelephone&gt;|&lt;email or empty&gt;'), i.e. the identity key
361	     * without the household segment. Two owners share an identity when this value is equal;
362	     * because the telephone is part of it, members of one household with different telephones
363	     * do not collide. A {@code null} email contributes the empty string.
364	     */
365	    private static String identityContact(Owner owner) {
366	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
367	        String email = owner.getEmail() == null ? "" : owner.getEmail();
368	        return telephone + "|" + email;
369	    }
370	
371	    /**
372	     * Normalize a telephone number to E.164 form.
373	     *
374	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
375	     * explicit leading {@code '+'} and country code it is kept; otherwise the
376	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
377	     * dropped from the national digits. The result must contain 8 to 15 digits
378	     * after the {@code '+'}, and — for a recognised country calling code — exactly
379	     * the national-number length that code mandates ({@code '+61'} => 9 national
380	     * digits, {@code '+1'} => 10).
381	     *
382	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
383	     *         the input is absent or cannot form a valid E.164 number.
384	     */
385	    private static String toE164(String raw) {
386	        if (raw == null) {
387	            return null;
388	        }
389	        String trimmed = raw.trim();
390	        boolean hasCountryCode = trimmed.startsWith("+");
391	        // Strip spaces, dashes and brackets.
392	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
393	        String digits;
394	        if (hasCountryCode) {
395	            // Keep the explicit country code; drop the leading '+' for validation.
396	            digits = stripped.substring(1);
397	        } else {
398	            // No country code: assume '+61' and drop a single leading '0'.
399	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
400	            digits = "61" + national;
401	        }
402	        if (!digits.matches("\\d{8,15}")) {
403	            return null;
404	        }
405	        // For a recognised country calling code, enforce the exact national-number length it
406	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
407	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
408	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
409	                .sorted((a, b) -> b.length() - a.length()).toList()) {
410	            if (digits.startsWith(countryCode)) {
411	                int nationalLength = digits.length() - countryCode.length();
412	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
413	                    return null;
414	                }
415	                break;
416	            }
417	        }
418	        return "+" + digits;
419	    }
420	
421	    /**
422	     * Count the existing owners whose first and last name match the given names,
423	     * compared case-insensitively. Used to record an owner's namesake count at the
424	     * moment before it is created.
425	     */
426	    private int countNamesakes(String firstName, String lastName) {
427	        return (int) this.clinicService.findAllOwners().stream()
428	            .filter(existing -> existing.getFirstName() != null
429	                && existing.getFirstName().equalsIgnoreCase(firstName)
430	                && existing.getLastName() != null
431	                && existing.getLastName().equalsIgnoreCase(lastName))
432	            .count();
433	    }
434	
435	    /**
436	     * Count the existing owners in the same household as the given owner, i.e. those sharing its
437	     * computed householdId (derived from the normalized last name and postcode). Used, together
438	     * with the owner being created, to derive the household size recorded on the owner.
439	     */
440	    private int countHouseholdMembers(Owner owner) {
441	        String householdId = ownerMapper.householdId(owner);
442	        return (int) this.clinicService.findAllOwners().stream()
443	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
444	            .count();
445	    }
446	
447	    /**
448	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
449	     * of: one sharing the same last name (compared case-insensitively) and the same postcode, but
450	     * carrying a different normalized telephone. Owners without a postcode never match (the postcode
451	     * must be shared). When several existing owners match, the one with the lowest id is returned so
452	     * the result is deterministic. Returns {@code null} when there is no such match.
453	     */
454	    private Owner findPossibleDuplicate(Owner candidate) {
455	        if (candidate.getPostcode() == null) {
456	            return null;
457	        }
458	        return this.clinicService.findAllOwners().stream()
459	            .filter(existing -> existing.getLastName() != null
460	                && existing.getLastName().equalsIgnoreCase(candidate.getLastName())
461	                && candidate.getPostcode().equals(existing.getPostcode())
462	                && !candidate.getTelephone().equals(existing.getTelephone()))
463	            .min(java.util.Comparator.comparing(Owner::getId))
464	            .orElse(null);
465	    }
466	
467	    /**
468	     * Build the owner's customer code, formatted {@code '<REGION>-<HASH8>'}.
469	     *
470	     * <p>{@code REGION} is the region derived from the owner's postcode (see
471	     * {@link #deriveRegion}). {@code HASH8} is the first 8 upper-case hex characters of the
472	     * SHA-256 of the normalized telephone concatenated with the last name
473	     * (e.g. {@code 'NSW-1A2B3C4D'}).
474	     */
475	    private String customerCode(Owner owner) {
476	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
477	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
478	        return region + "-" + hash8;
479	    }
480	
481	    /**
482	     * Derive the owner's region, preferring the postcode. The postcode is matched against
483	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
484	     * it is absent or in no known range does this fall back to the fixed city-to-region table
485	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
486	     */
487	    private static String deriveRegion(String postcode, String city) {
488	        if (postcode != null && postcode.matches("\\d{4}")) {
489	            int value = Integer.parseInt(postcode);
490	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
491	                int[] range = entry.getValue();
492	                if (value >= range[0] && value <= range[1]) {
493	                    return entry.getKey();
494	                }
495	            }
496	        }
497	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
498	    }
499	
500	    /**
501	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
502	     * bytes of {@code value}.
503	     */
504	    private static String sha256HexUpper(String value, int length) {
505	        try {
506	            byte[] digest = MessageDigest.getInstance("SHA-256")
507	                .digest(value.getBytes(StandardCharsets.UTF_8));
508	            StringBuilder sb = new StringBuilder(digest.length * 2);
509	            for (byte b : digest) {
510	                sb.append(String.format("%02X", b));
511	            }
512	            return sb.substring(0, length);
513	        }
514	        catch (NoSuchAlgorithmException e) {
515	            throw new IllegalStateException(e);
516	        }
517	    }
518	
519	    /**
520	     * Count the existing owners located in the given city, compared case-insensitively.
521	     * Used to derive the per-city 4-digit sequence in the customer code.
522	     */
523	    private int countOwnersInCity(String city) {
524	        return (int) this.clinicService.findAllOwners().stream()
525	            .filter(existing -> existing.getCity() != null
526	                && existing.getCity().equalsIgnoreCase(city))
527	            .count();
528	    }
529	
530	    /**
531	     * Count the existing owners whose registration date is the given (adjusted business) date.
532	     * Used to enforce the per-day sign-up limit.
533	     */
534	    private int countOwnersRegisteredOn(LocalDate date) {
535	        return (int) this.clinicService.findAllOwners().stream()
536	            .filter(existing -> date.equals(existing.getRegistrationDate()))
537	            .count();
538	    }
539	
540	    /**
541	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
542	     * the following Monday; a weekday is returned unchanged.
543	     */
544	    private static LocalDate toBusinessDay(LocalDate date) {
545	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
546	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
547	            date = date.plusDays(1);
548	        }
549	        return date;
550	    }
