556	        if (currentOwner == null) {
557	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
558	        }
559	        if (!normalizeEmail(ownerFieldsDto)) {
560	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
561	        }
562	        if (!normalizePostcode(ownerFieldsDto)) {
563	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
564	        }
565	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
566	        if (normalizedTelephone == null) {
567	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
568	        }
569	        currentOwner.setAddress(ownerFieldsDto.getAddress());
570	        currentOwner.setCity(ownerFieldsDto.getCity());
571	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
572	        currentOwner.setLastName(ownerFieldsDto.getLastName());
573	        currentOwner.setTelephone(normalizedTelephone);
574	        currentOwner.setEmail(ownerFieldsDto.getEmail());
575	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
576	        this.clinicService.saveOwner(currentOwner);
