18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    /** Fixed city-to-region table used to derive an owner's region. */
25	    java.util.Map<String, String> CITY_REGION =
26	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
27	
28	    @Mapping(target = "displayName",
29	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
30	    @Mapping(target = "initials", expression = "java(initials(owner))")
31	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
32	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
33	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
34	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
35	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
36	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
37	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
38	    @Mapping(target = "locality", expression = "java(locality(owner))")
39	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
40	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
41	    OwnerDto toOwnerDto(Owner owner);
42	
43	    /**
44	     * The owner's age band, derived from the supplied birthDate as at the
45	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18-64, and 'SENIOR' when
46	     * 65 or older. Returns {@code null} when no birthDate (or registrationDate) is
47	     * available, so the field is omitted for owners without a supplied birth date.
48	     */
49	    default String ageBand(Owner owner) {
50	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
51	            return null;
52	        }
53	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
54	        if (age < 18) {
55	            return "MINOR";
56	        }
57	        if (age < 65) {
58	            return "ADULT";
59	        }
60	        return "SENIOR";
61	    }
62	
63	    /**
64	     * The owner's preferred contact channel: 'EMAIL' when an email address is present,
65	     * otherwise 'PHONE'.
66	     */
67	    default String contactPreference(Owner owner) {
68	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
69	        return hasEmail ? "EMAIL" : "PHONE";
70	    }
71	
72	    /**
73	     * The owner's region, read from the {@code <REGION>-<HASH8>} customer code assigned on
74	     * creation: the segment before the first '-'. Returns 'UNKNOWN' when no customer code has
75	     * been assigned (e.g. legacy owners predating the region-and-hash identity).
76	     */
77	    default String locality(Owner owner) {
78	        String code = owner.getCustomerCode();
79	        if (code != null) {
80	            int dash = code.indexOf('-');
81	            if (dash > 0) {
82	                return code.substring(0, dash);
83	            }
84	        }
85	        return "UNKNOWN";
86	    }
87	
88	    /**
89	     * The owner's membership points. Starts at 0; gains 2 when an email address is present,
90	     * 1 when the owner has no namesakes (namesakeCount is 0), 2 for a household of 3 or more
91	     * (householdSize is 3 or greater), and 3 when the owner's tenure exceeds 365 days (more
92	     * than 365 whole days between the registrationDate and today). Because a newly created
93	     * owner has zero tenure, the tenure points are only earned once more than a year has
94	     * passed since registration.
95	     */
96	    default Integer membershipPoints(Owner owner) {
97	        int points = 0;
98	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
99	        if (hasEmail) {
100	            points += 2;
101	        }
102	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
103	        if (noNamesakes) {
104	            points += 1;
105	        }
106	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
107	            points += 2;
108	        }
109	        if (owner.getRegistrationDate() != null
110	            && java.time.temporal.ChronoUnit.DAYS.between(owner.getRegistrationDate(),
111	                java.time.LocalDate.now()) > 365) {
112	            points += 3;
113	        }
114	        return points;
115	    }
116	
117	    /**
118	     * The owner's numeric membership level, derived from {@link #membershipPoints(Owner)}:
119	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
120	     * for 6 or more points.
121	     */
122	    default Integer membershipLevel(Owner owner) {
123	        int points = membershipPoints(owner);
124	        if (points <= 1) {
125	            return 1;
126	        }
127	        if (points <= 3) {
128	            return 2;
129	        }
130	        if (points <= 5) {
131	            return 3;
132	        }
133	        return 4;
134	    }
135	
136	    /**
137	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
138	     * customerCode. Returns {@code null} when the customerCode has not been assigned.
139	     */
140	    default Integer checkDigit(Owner owner) {
141	        if (owner.getCustomerCode() == null) {
142	            return null;
143	        }
144	        String s = owner.getCustomerCode();
145	        int sum = 0;
146	        boolean dbl = true;
147	        for (int i = s.length() - 1; i >= 0; i--) {
148	            char c = s.charAt(i);
149	            if (c < '0' || c > '9') {
150	                continue;
151	            }
152	            int d = c - '0';
153	            if (dbl) {
154	                d *= 2;
155	                if (d > 9) {
156	                    d -= 9;
157	                }
158	            }
159	            sum += d;
160	            dbl = !dbl;
161	        }
162	        return (10 - (sum % 10)) % 10;
163	    }
164	
165	    /**
166	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY
167	     * is the last two digits of the registrationDate year (e.g. 'NSW-1A2B3C4D-M26').
168	     */
169	    default String membershipNumber(Owner owner) {
170	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
171	            return null;
172	        }
173	        return String.format("%s-M%02d", owner.getCustomerCode(),
174	            owner.getRegistrationDate().getYear() % 100);
175	    }
176	
177	    /**
178	     * Known E.164 country calling codes used to split the stored telephone into its
179	     * country code and national number for display. Longer codes are matched first so a
180	     * '+61' number is not mistaken for a '+6...' one.
181	     */
182	    java.util.List<String> COUNTRY_CODES = java.util.List.of("61", "1");
183	
184	    /**
185	     * The stored E.164 telephone formatted for humans: the country code, a space, and the
186	     * national digits grouped in threes (e.g. '+61412345678' becomes '+61 412 345 678').
187	     * Returns the stored value unchanged when it is {@code null} or not in the expected
188	     * '+'-prefixed all-digits E.164 form.
